import numpy as np
def read_xyz(p):
    lines = open(p).read().splitlines()
    n = int(lines[0]); els=[]; xyz=[]
    for l in lines[2:2+n]:
        t=l.split(); els.append(t[0]); xyz.append([float(x) for x in t[1:4]])
    return els, np.array(xyz)
els, xyz = read_xyz("init.xyz")
ico = els.index("Co")
for i,e in enumerate(els):
    d = np.linalg.norm(xyz[i]-xyz[ico])
    if e!="Co" and d < 2.6:
        print(i, e, round(d,3))
