import numpy as np, itertools
def read_xyz(p):
    lines = open(p).read().splitlines()
    n = int(lines[0]); els=[]; xyz=[]
    for l in lines[2:2+n]:
        t=l.split(); els.append(t[0]); xyz.append([float(x) for x in t[1:4]])
    return els, np.array(xyz)
els, xyz = read_xyz("init.xyz")
coords=[3,13,22]
for a,b in itertools.combinations(coords,2):
    v1=xyz[a]-xyz[0]; v2=xyz[b]-xyz[0]
    print("N-Co-N",a,b,round(np.degrees(np.arccos(v1@v2/np.linalg.norm(v1)/np.linalg.norm(v2))),1))
for a in coords:
    v1=xyz[1]-xyz[0]; v2=xyz[a]-xyz[0]
    print("C-Co-N",a,round(np.degrees(np.arccos(v1@v2/np.linalg.norm(v1)/np.linalg.norm(v2))),1))
iB=els.index("B")
print("B at dist from Co:", round(np.linalg.norm(xyz[iB]-xyz[0]),2))
for i,e in enumerate(els):
    d=np.linalg.norm(xyz[i]-xyz[0])
    if e=="H" and d<2.6: print("H close:",i,round(d,2))
